	private static class ChangeCollector : AutoCloseable {
		private AddCollector a;
		private RemoveCollector r;

		public ChangeCollector(LogicalBreakpointsChangeListener l) {
			Set<LogicalBreakpoint> updated = new();
			a = new AddCollector(l, updated);
			r = new RemoveCollector(l, updated);
		}

		/* @Override */
		public void close() {
			r.deconflict();
			a.deconflict();
