	private class TraceBreakpointsListener : TraceDomainObjectListener {
		private InfoPerTrace info;
		private ChangeCollector c;

		public TraceBreakpointsListener(InfoPerTrace info) {
			// TODO: What if recorder advances past a trace breakpoint?
			// Tends never to happen during recording, since upper is unbounded
			// (Same in break provider for locations)
			this.info = info;

			listenForUntyped(DomainObjectEvent.RESTORED, e => objectRestored());
			listenFor(TraceEvents.BREAKPOINT_ADDED, this.breakpointAdded);
			listenFor(TraceEvents.BREAKPOINT_CHANGED, this.breakpointChanged);
			listenFor(TraceEvents.BREAKPOINT_LIFESPAN_CHANGED, this.breakpointLifespanChanged);
			listenFor(TraceEvents.BREAKPOINT_DELETED, this.breakpointDeleted);
		}

		/* @Override */
		public void domainObjectChanged(DomainObjectChangedEvent ev) {
			processChange(c => {
				// NB. This works because processEvent dispatches on a single thread
				this.c = c;
				base.domainObjectChanged(ev);
				this.c = null;
			}, "trace-domainObjectChanged");
		}

		private void objectRestored() {
			info.reloadBreakpoints(c);
		}

		private void breakpointAdded(TraceBreakpointLocation tb) {
			if (!tb.isValid(info.snap)) {
				return;
			}
			try {
				info.trackTraceBreakpoint(c, tb, getMode(info.trace), false);
			}
			catch (TrackedTooSoonException e) {
				Msg.info(this,
					"Ignoring " + tb + " added until service has finished loading its trace");
			}
		}

		private void breakpointChanged(TraceBreakpointLocation tb) {
			if (!tb.isValid(info.snap)) {
				return;
			}
			try {
				info.trackTraceBreakpoint(c, tb, getMode(info.trace), true);
			}
			catch (TrackedTooSoonException e) {
				Msg.info(this,
					"Ignoring " + tb + " changed until service has finished loading its trace");
			}
			catch (NoSuchElementException e) {
				// TODO: This catch clause should not be necessary.
				Msg.error(this, "!!!! Object-based breakpoint emitted event without a spec: " + tb);
			}
		}

		private void breakpointLifespanChanged(AddressSpace spaceIsNull,
				TraceBreakpointLocation tb, Lifespan oldSpan, Lifespan newSpan) {
			// NOTE: User/script probably modified historical breakpoint
			bool isInOld = oldSpan.contains(info.snap);
			bool isInNew = newSpan.contains(info.snap);
			if (isInOld == isInNew) {
				return;
			}
			if (isInOld) {
				info.forgetTraceBreakpoint(c.r, tb);
			}
			else {
				try {
					info.trackTraceBreakpoint(c, tb, getMode(info.trace), false);
				}
				catch (TrackedTooSoonException e) {
					Msg.info(this, "Ignoring " + tb +
						" span changed until service has finished loading its trace");
				}
			}
		}

		private void breakpointDeleted(TraceBreakpointLocation tb) {
			// Could check snap, but might as well just be sure it's gone
			info.forgetTraceBreakpoint(c.r, tb);
		}
	}

	private class ProgramBreakpointsListener : TraceDomainObjectListener {
		private InfoPerProgram info;
		private ChangeCollector c;

		public ProgramBreakpointsListener(InfoPerProgram info) {
			this.info = info;

			listenForUntyped(DomainObjectEvent.RESTORED, e => objectRestored());
			listenForUntyped(ProgramEvent.BOOKMARK_ADDED,
				onBreakpoint(this.breakpointBookmarkAdded));
			listenForUntyped(ProgramEvent.BOOKMARK_CHANGED,
				onBreakpoint(this.breakpointBookmarkChanged));
			listenForUntyped(ProgramEvent.BOOKMARK_REMOVED,
				onBreakpoint(this.breakpointBookmarkDeleted));
		}

		/* @Override */
		public void domainObjectChanged(DomainObjectChangedEvent ev) {
			processChange(c => {
				// NB. This works because processEvent dispatches on a single thread
				this.c = c;
				base.domainObjectChanged(ev);
				this.c = null;
			}, "program-domainObjectChanged");
		}

		private void objectRestored() {
			info.reloadBreakpoints(c);
			// NOTE: logical breakpoints should know which traces are affected
		}

		private Consumer<DomainObjectChangeRecord> onBreakpoint(Consumer<Bookmark> handler) {
			return rec => {
				ProgramChangeRecord pcrec = (ProgramChangeRecord) rec; // Eww
				Bookmark pb = (Bookmark) pcrec.getObject(); // So gross
				string bmType = pb.getTypeString();
				if (LogicalBreakpoint.ENABLED_BOOKMARK_TYPE.equals(bmType) ||
					LogicalBreakpoint.DISABLED_BOOKMARK_TYPE.equals(bmType)) {
					handler.accept(pb);
				}
			};
		}

		private void breakpointBookmarkAdded(Bookmark pb) {
			info.trackProgramBreakpoint(c.a, pb);
		}

		private void breakpointBookmarkChanged(Bookmark pb) {
			breakpointBookmarkDeleted(pb, true);
			breakpointBookmarkAdded(pb);
		}

		private void breakpointBookmarkDeleted(Bookmark pb) {
			breakpointBookmarkDeleted(pb, false);
		}

		private void breakpointBookmarkDeleted(Bookmark pb, bool forChange) {
			info.forgetProgramBreakpoint(c.r, pb, forChange);
		}
	}

	protected abstract class AbstractInfo {
		NavigableMap<Address, Set<LogicalBreakpointInternal>> logicalByAddress =
			new();

		public AbstractInfo() {
		}

		protected abstract void dispose(RemoveCollector r);

		protected abstract LogicalBreakpointInternal createLogicalBreakpoint(Address address,
				long length, Collection<TraceBreakpointKind> kinds);

		protected LogicalBreakpointInternal getOrCreateLogicalBreakpointFor(AddCollector a,
				Address address, TraceBreakpointLocation tb, long snap)
    {
			Set<LogicalBreakpointInternal> set =
				logicalByAddress.computeIfAbsent(address, __ => new());
			foreach (LogicalBreakpointInternal lb in set) {
				if (lb.canMerge(tb, snap)) {
					return lb;
				}
			}

			LogicalBreakpointInternal lb =
				createLogicalBreakpoint(address, tb.getLength(snap), tb.getKinds(snap));
			set.add(lb);
			a.added(lb);
			return lb;
		}

		protected bool removeLogicalBreakpoint(Address address, LogicalBreakpoint lb) {
			foreach (TraceBreakpointLocation tb in lb.getTraceBreakpoints()) {
				InfoPerTrace info = traceInfos.get(tb.getTrace());
				if (info != null) {
					info.logicalByBreakpoint.remove(tb);
				}
			}
			Set<LogicalBreakpointInternal> set = logicalByAddress.get(address);
			if (set == null) {
				return false;
			}
			if (!set.remove(lb)) {
				return false;
			}
			if (set.isEmpty()) {
				logicalByAddress.remove(address);
			}
			return true;
		}

		protected bool isMismapped(LogicalBreakpointInternal lb) {
			if (!(lb is MappedLogicalBreakpoint)) {
				return false; // Can't be mis-mapped if not mapped
			}
			Set<Trace> extraneous = new(lb.getMappedTraces());
			extraneous.removeAll(traceInfos.keySet());
			if (!extraneous.isEmpty()) {
				return true;
			}
			foreach (InfoPerTrace ti in traceInfos.values()) {
				TraceLocation loc = ti.toDynamicLocation(lb.getProgramLocation());
				if (loc == null) {
					if (lb.getTraceAddress(ti.trace) != null) {
						return true;
					}
					continue;
				}
				if (!loc.getAddress().equals(lb.getTraceAddress(ti.trace))) {
					return true;
				}
			}
			return false;
		}

		protected void forgetMismappedBreakpoints(RemoveCollector r, Set<Trace> additionalTraces,
				Set<Program> additionalPrograms) {
			foreach (Set<LogicalBreakpointInternal> set in List.copyOf(logicalByAddress.values())) {
				foreach (LogicalBreakpointInternal lb in Set.copyOf(set)) {
					if (isMismapped(lb)) {
						removeLogicalBreakpointGlobally(lb);
						r.removed(lb);
						additionalTraces.addAll(lb.getParticipatingTraces());
					}
				}
			}
		}
	}

	protected class InfoPerTrace : AbstractInfo {
		Map<TraceBreakpointLocation, LogicalBreakpointInternal> logicalByBreakpoint =
			new();

		Trace trace;
		TraceBreakpointsListener breakpointListener;

		Target target;
		long snap = -1;

		public InfoPerTrace(Trace trace) {
			this.trace = Objects.requireNonNull(trace);
			this.breakpointListener = new TraceBreakpointsListener(this);

			trace.addListener(breakpointListener);
		}

		protected void setTargetAndSnap(Target target, long snap, ChangeCollector c) {
			if (this.target == target && this.snap == snap) {
				return;
			}
			this.target = target;
			this.snap = snap;

			foreach (InfoPerProgram info in programInfos.values()) {
				// This is heavy, but not sure a better method
				// Could examine mapping service to narrow down relevant programs...
				info.reloadBreakpoints(c);
			}
			reloadBreakpoints(c);
		}

		/* @Override */
		protected LogicalBreakpointInternal createLogicalBreakpoint(Address address, long length,
				Collection<TraceBreakpointKind> kinds) {
			LoneLogicalBreakpoint lb =
				new LoneLogicalBreakpoint(tool, trace, address, length, kinds);
			lb.setTarget(trace, target);
			return lb;
		}

		/* @Override */
		protected void dispose(RemoveCollector r) {
			trace.removeListener(breakpointListener);
			forgetAllBreakpoints(r);
		}

		protected void reloadBreakpoints(ChangeCollector c) {
			forgetTraceInvalidBreakpoints(c.r);
			trackTraceBreakpoints(c);
		}

		protected void forgetAllBreakpoints(RemoveCollector r) {
			foreach (TraceBreakpointLocation tb in List.copyOf(logicalByBreakpoint.keySet())) {
				forgetTraceBreakpoint(r, tb);
			}
		}

		protected void forgetTraceInvalidBreakpoints(RemoveCollector r) {
			/**
			 * Breakpoint can become invalid because it is itself invalid (deleted), because the
			 * snap has changed to where it's no longer present, because the mapping to static space
			 * has changed or become invalid, or because it has no live breakpoint in target mode.
			 */
			ControlMode mode = getMode(trace);

			foreach (Entry<TraceBreakpointLocation, LogicalBreakpointInternal> ent in Set
					.copyOf(logicalByBreakpoint.entrySet())) {
				TraceBreakpointLocation tb = ent.getKey();
				LogicalBreakpoint lb = ent.getValue();
				if (!mode.useEmulatedBreakpoints() &&
					(target == null || !target.isBreakpointValid(tb))) {
					forgetTraceBreakpoint(r, tb);
					continue;
				}
				if (!trace.getBreakpointManager().getAllBreakpointLocations().contains(tb)) {
					forgetTraceBreakpoint(r, tb);
					continue;
				}
				if (!tb.isValid(snap)) {
					forgetTraceBreakpoint(r, tb);
					continue;
				}
				ProgramLocation progLoc = computeStaticLocation(tb);
				if (!Objects.equals(lb.getProgramLocation(), progLoc)) {
					// NOTE: This can happen to Lone breakpoints.
					// (mis)Mapped ones should already be forgotten.
					forgetTraceBreakpoint(r, tb);
					continue;
				}
			}
		}

		protected void trackTraceBreakpoints(ChangeCollector c) {
			ControlMode mode = getMode(trace);
			if (!mode.useEmulatedBreakpoints() && target == null) {
				return;
			}
			Collection<TraceBreakpointLocation> visible = new();
			foreach (AddressRange range in trace.getBaseAddressFactory().getAddressSet()) {
				visible.addAll(trace.getBreakpointManager()
						.getBreakpointsIntersecting(Lifespan.at(snap), range));
			}
			trackTraceBreakpoints(c, visible, mode);
		}

		protected void trackTraceBreakpoints(ChangeCollector c,
				Collection<TraceBreakpointLocation> breakpoints, ControlMode mode) {
			foreach (TraceBreakpointLocation tb in breakpoints) {
				try {
					/**
					 * Sadly, even something as simple as toggling a breakpoint can cause so many
					 * events that the manager punts to OBJECT_RESTORED. Thus, we have to set
					 * forceUpdate here.
					 */
					trackTraceBreakpoint(c, tb, mode, true);
				}
				catch (TrackedTooSoonException e) {
					// This can still happen during reload (on OBJECT_RESTORED)
					Msg.warn(this, "Might have lost track of a breakpoint: " + tb);
				}
			}
		}

		protected ProgramLocation computeStaticLocation(TraceBreakpointLocation tb) {
			if (traceManager == null || !traceManager.getOpenTraces().contains(tb.getTrace())) {
				/**
				 * Mapping service will throw an exception otherwise. NB: When trace is opened,
				 * mapping service will fire events causing this service to coalesce affected
				 * breakpoints.
				 */
				return null;
			}
			Address minAddress = tb.getMinAddress(snap);
			if (minAddress == null) {
				return null;
			}
			return mappingService.getOpenMappedLocation(
				new DefaultTraceLocation(trace, null, Lifespan.at(snap), minAddress));
		}

		protected void trackTraceBreakpoint(ChangeCollector c, TraceBreakpointLocation tb,
				ControlMode mode, bool forceUpdate)
    {
			if (!mode.useEmulatedBreakpoints() &&
				(target == null || !target.isBreakpointValid(tb))) {
				return;
			}
			Address traceAddr = tb.getMinAddress(snap);
			if (traceAddr == null) {
				LogicalBreakpointInternal oldLb = logicalByBreakpoint.remove(tb);
				if (oldLb != null) {
					// Happens when existing location's range is deleted
					doRemoveFromLogicalBreakpoint(c.r, oldLb, tb);
				}
				return; // Will update via breakpointChanged when address is set
			}
			ProgramLocation progLoc = computeStaticLocation(tb);
			LogicalBreakpointInternal lb;
			if (progLoc != null) {
				InfoPerProgram progInfo = programInfos.get(progLoc.getProgram());
				lb = progInfo.getOrCreateLogicalBreakpointFor(c.a, progLoc.getByteAddress(), tb,
					snap);
			}
			else {
				lb = getOrCreateLogicalBreakpointFor(c.a, traceAddr, tb, snap);
			}
			System.Diagnostics.Debug.Assert(logicalByAddress.get(traceAddr).contains(lb);
			LogicalBreakpointInternal oldLb = logicalByBreakpoint.put(tb, lb);
			if (oldLb != lb && oldLb != null) {
				// Happens when existing location's range changes
				doRemoveFromLogicalBreakpoint(c.r, oldLb, tb);
			}
			if (lb.trackBreakpoint(tb) || forceUpdate) {
				c.a.updated(lb);
			}
		}

		protected LogicalBreakpointInternal doRemoveFromLogicalBreakpoint(RemoveCollector r,
				LogicalBreakpointInternal lb, TraceBreakpointLocation tb) {
			if (lb == null || !lb.untrackBreakpoint(tb)) {
				return null;
			}
			if (lb.isEmpty()) {
				// If being disposed, this info is no longer in the map
				removeLogicalBreakpoint(lb.getTraceAddress(trace), lb);
				removeLogicalBreakpointGlobally(lb);
				r.removed(lb);
			}
			else {
				r.updated(lb);
			}
			return lb;
		}

		protected LogicalBreakpointInternal removeFromLogicalBreakpoint(RemoveCollector r,
				TraceBreakpointLocation tb) {
			LogicalBreakpointInternal lb = logicalByBreakpoint.remove(tb);
			return doRemoveFromLogicalBreakpoint(r, lb, tb);
		}

		protected void forgetTraceBreakpoint(RemoveCollector r, TraceBreakpointLocation tb) {
			LogicalBreakpointInternal lb = removeFromLogicalBreakpoint(r, tb);
			if (lb == null) {
				return; // Warnings already logged
			}
			System.Diagnostics.Debug.Assert(lb.isEmpty() == (logicalByAddress.get(lb.getTraceAddress(trace)) == null ||
				!logicalByAddress.get(tb.getMinAddress(snap)).contains(lb)));
		}

		public TraceLocation toDynamicLocation(ProgramLocation loc) {
			if (mappingService == null) {
				// Must be shutting down
				return null;
			}
			return mappingService.getOpenMappedLocation(trace, loc, snap);
		}
	}

	protected class InfoPerProgram, AbstractInfo {
		Program program);
		ProgramBreakpointsListener breakpointListener;

		public InfoPerProgram(Program program) {
			this.program = program;
			this.breakpointListener = new ProgramBreakpointsListener(this);

			program.addListener(breakpointListener);
		}

		protected void mapTraceAddresses(LogicalBreakpointInternal lb) {
			foreach (InfoPerTrace ti in traceInfos.values()) {
				TraceLocation loc = ti.toDynamicLocation(lb.getProgramLocation());
				if (loc == null) {
					continue;
				}
				lb.setTraceAddress(ti.trace, loc.getAddress());
				lb.setTarget(ti.trace, ti.target);
				ti.logicalByAddress.computeIfAbsent(loc.getAddress(), __ => new())
						.add(lb);
			}
		}

		/* @Override */
		protected LogicalBreakpointInternal createLogicalBreakpoint(Address address, long length,
				Collection<TraceBreakpointKind> kinds) {
			MappedLogicalBreakpoint lb =
				new MappedLogicalBreakpoint(tool, program, address, length, kinds);
			mapTraceAddresses(lb);
			return lb;
		}

		protected LogicalBreakpointInternal getOrCreateLogicalBreakpointFor(AddCollector a,
				Bookmark pb) {
			Address address = pb.getAddress();
			Set<LogicalBreakpointInternal> set =
				logicalByAddress.computeIfAbsent(address, __ => new());
			foreach (LogicalBreakpointInternal lb in set) {
				if (lb.canMerge(program, pb)) {
					return lb;
				}
			}

			LogicalBreakpointInternal lb = createLogicalBreakpoint(address,
				ProgramBreakpoint.lengthFromBookmark(pb), ProgramBreakpoint.kindsFromBookmark(pb));
			set.add(lb);
			a.added(lb);
			return lb;
		}

		protected LogicalBreakpointInternal removeFromLogicalBreakpoint(RemoveCollector r,
				Bookmark pb, bool forChange) {
			Address address = pb.getAddress();
			Set<LogicalBreakpointInternal> set = logicalByAddress.get(address);
			if (set == null) {
				Msg.error(this, "Breakpoint " + pb + " was not tracked before removal!");
				return null;
			}
			foreach (LogicalBreakpointInternal lb in Set.copyOf(set)) {
				if (lb.untrackBreakpoint(program, pb)) {
					if (lb.isEmpty() && !forChange) {
						// If being disposed, this info may no longer be in the map
						removeLogicalBreakpoint(address, lb);
						removeLogicalBreakpointGlobally(lb);
						r.removed(lb);
					}
					else {
						r.updated(lb);
					}
					return lb;
				}
			}
			Msg.error(this, "Breakpoint " + pb + " was not tracked before removal!");
			return null;
		}

		/* @Override */
		protected void dispose(RemoveCollector r) {
			program.removeListener(breakpointListener);
			forgetAllBreakpoints(r);
		}

		protected void reloadBreakpoints(ChangeCollector c) {
			forgetProgramInvalidBreakpoints(c.r);
			trackAllProgramBreakpoints(c.a);
		}

		protected void forgetAllBreakpoints(RemoveCollector r) {
			Collection<Bookmark> marks = new();
			program.getBookmarkManager()
					.getBookmarksIterator(LogicalBreakpoint.ENABLED_BOOKMARK_TYPE)
					.forEachRemaining(marks.add);
			program.getBookmarkManager()
					.getBookmarksIterator(LogicalBreakpoint.DISABLED_BOOKMARK_TYPE)
					.forEachRemaining(marks.add);
			foreach (Bookmark pb in marks) {
				forgetProgramBreakpoint(r, pb, false);
			}
		}

		protected void forgetProgramInvalidBreakpoints(RemoveCollector r) {
			// Breakpoint can become invalid because it is itself invalid (deleted)
			// Or because its address moved (I think this can happen if the containing block moves)

			/**
			 * NOTE: A change in the program (other than bookmark address), should not affect the
			 * mapped trace addresses. That would require a change in the trace.
			 */
			foreach (Set<LogicalBreakpointInternal> set in List.copyOf(logicalByAddress.values())) {
				foreach (LogicalBreakpointInternal lb in Set.copyOf(set)) {
					foreach (Bookmark pb in lb.getProgramBookmarksValidOrNot()) {
						if (pb != program.getBookmarkManager().getBookmark(pb.getId())) {
							forgetProgramBreakpoint(r, pb, false);
							continue;
						}
						if (!lb.getProgramLocation().getByteAddress().equals(pb.getAddress())) {
							forgetProgramBreakpoint(r, pb, false);
							continue;
						}
					}
				}
			}
		}

		protected void trackAllProgramBreakpoints(AddCollector a) {
			BookmarkManager bookmarks = program.getBookmarkManager();
			trackProgramBreakpoints(a, IteratorUtils.asIterable(
				bookmarks.getBookmarksIterator(LogicalBreakpoint.ENABLED_BOOKMARK_TYPE)));
			trackProgramBreakpoints(a, IteratorUtils.asIterable(
				bookmarks.getBookmarksIterator(LogicalBreakpoint.DISABLED_BOOKMARK_TYPE)));
		}

		protected void trackProgramBreakpoints(AddCollector a, Iterable<Bookmark> bptMarks) {
			foreach (Bookmark pb in bptMarks) {
				trackProgramBreakpoint(a, pb);
			}
		}

		protected void trackProgramBreakpoint(AddCollector a, Bookmark pb) {
			LogicalBreakpointInternal lb = getOrCreateLogicalBreakpointFor(a, pb);
			System.Diagnostics.Debug.Assert(logicalByAddress.get(pb.getAddress()).contains(lb);
			if (lb.trackBreakpoint(pb)) {
				a.updated(lb);
			}
		}

		protected void forgetProgramBreakpoint(RemoveCollector r, Bookmark pb, bool forChange) {
			LogicalBreakpointInternal lb = removeFromLogicalBreakpoint(r, pb, forChange);
			if (lb == null) {
				return;
			}
			System.Diagnostics.Debug.Assert(isConsistentAfterRemoval(pb, lb, forChange));
		}

		private bool isConsistentAfterRemoval(Bookmark pb, LogicalBreakpointInternal lb,
				bool forChange) {
			Set<LogicalBreakpointInternal> present = logicalByAddress.get(pb.getAddress());
			bool shouldBeAbsent = lb.isEmpty() && !forChange;
			bool isAbsent = present == null || !present.contains(lb);
			return shouldBeAbsent == isAbsent;
		}
	}

	// @AutoServiceConsumed via method
	private DebuggerTargetService targetService;
	/* @AutoServiceConsumed */
	private DebuggerTraceManagerService traceManager;
	// @AutoServiceConsumed via method
	private DebuggerStaticMappingService mappingService;
	// @AutoServiceConsumed via method
	private DebuggerControlService controlService;
	/* @SuppressWarnings("unused") */
	private AutoService.Wiring autoServiceWiring;

	private object @lock = new object();
	private ListenerSet<LogicalBreakpointsChangeListener> changeListeners =
		new(typeof(LogicalBreakpointsChangeListener), true);

	private TrackTargetsListener targetsListener = new TrackTargetsListener();
	private TrackMappingsListener mappingListener = new TrackMappingsListener();
	private TrackModesListener modeListener = new TrackModesListener();

	private Map<Trace, InfoPerTrace> traceInfos = new();
	private Map<Program, InfoPerProgram> programInfos = new();
	private Collection<AbstractInfo> allInfos =
		new(traceInfos.values(), programInfos.values());
	private ExecutorService executor = SwingExecutorService.MAYBE_NOW;

	public DebuggerLogicalBreakpointServicePlugin(PluginTool tool), base(tool)
    {
		this.autoServiceWiring = AutoService.wireServicesProvidedAndConsumed(this));
	}

	protected void processChange(Consumer<ChangeCollector> processor, string description) {
		executor.submit(() => {
			// Invoke change callbacks without the lock! (try must surround sync)
			try
{
    using (ChangeCollector c = new ChangeCollector(changeListeners.invoke()))
    {

				lock (@lock) {
					processor.accept(c);
				}
			
    }
}
			catch (Throwable t) {
				Msg.error(this, "Could not process event " + description, t);
			}
		});
	}

	protected void evtMappingsChanged(ChangeCollector c, Set<Trace> affectedTraces,
			Set<Program> affectedPrograms) {
		Set<Trace> additionalTraces = new(affectedTraces);
		Set<Program> additionalPrograms = new(affectedPrograms);
		// Though all mapped breakpoints are in program infos,
		// That program may not be in the affected list, esp., if just closed
		foreach (Trace t in affectedTraces) {
			InfoPerTrace info = traceInfos.get(t);
			if (info != null) {
				info.forgetMismappedBreakpoints(c.r, additionalTraces, additionalPrograms);
			}
		}
		foreach (Program p in affectedPrograms) {
			InfoPerProgram info = programInfos.get(p);
			if (info != null) {
				info.forgetMismappedBreakpoints(c.r, additionalTraces, additionalPrograms);
			}
		}
		// Load program breakpoints first, lest syncing with traces write garbage to program
		foreach (Program p in additionalPrograms) {
			InfoPerProgram info = programInfos.get(p);
			if (info != null) {
				info.reloadBreakpoints(c);
			}
		}
		foreach (Trace t in additionalTraces) {
			InfoPerTrace info = traceInfos.get(t);
			if (info != null) {
				info.reloadBreakpoints(c);
			}
		}
	}

	protected void evtModeChanged(ChangeCollector c, Trace trace) {
		InfoPerTrace info = traceInfos.get(trace);
		if (info != null) {
			info.reloadBreakpoints(c);
		}
	}

	protected void removeLogicalBreakpointGlobally(LogicalBreakpoint lb) {
		ProgramLocation pLoc = lb.getProgramLocation();
		if (pLoc != null) {
			InfoPerProgram info = programInfos.get(pLoc.getProgram());
			if (info != null) { // Maybe the program was just closed
				info.removeLogicalBreakpoint(pLoc.getByteAddress(), lb);
			}
		}
		foreach (Trace t in lb.getMappedTraces()) {
			Address tAddr = lb.getTraceAddress(t);
			InfoPerTrace info = traceInfos.get(t);
			if (info != null) { // Maybe the trace was just closed
				info.removeLogicalBreakpoint(tAddr, lb);
			}
		}
	}

	/* @AutoServiceConsumed */
